import math
from functools import reduce

def lcm(a, b):
    return abs(a*b) // math.gcd(a, b)

def lcm_range(start, end):
    """Calculates lcm(start, start+1, ..., end)"""
    if start > end:
        return 1
    return reduce(lcm, range(start, end + 1))

# Dictionary to store results: results[n][k] = x_k
results = {1: {}, 2: {}, 3: {}}
k_limit = 11 # Need k up to 10 to check x_{k+1} > x_k

print("--- Calculating x_k for n=1, 2, 3 for k=1 to 11 ---")
for n in [1, 2, 3]:
    results[n] = {}
    for k in range(1, k_limit + 1):
        # x_k = lcm(k, k+1, ..., k+n-1)
        start = k
        end = k + n - 1
        x_k = lcm_range(start, end)
        results[n][k] = x_k
        # print(f"n={n}, k={k}: x_k = {x_k}") # Too verbose, will save only necessary parts

print("\n--- Results Table (k=1 to 11) ---")
for n in [1, 2, 3]:
    print(f"\nN={n}:")
    for k in range(1, 12):
        print(f"  k={k}: x_k = {results[n][k]}")

# Specific check for n=3, comparing x_5 and x_6
x5_n3 = results[3][5]
x6_n3 = results[3][6]
print(f"\n--- Specific Check N=3 ---")
print(f"x_5 (n=3) = lcm(5, 6, 7) = {x5_n3}")
print(f"x_6 (n=3) = lcm(6, 7, 8) = {x6_n3}")
print(f"Is x_6 < x_5? {x6_n3 < x5_n3}")

