import math

def lcm(a, b):
    return abs(a*b) // math.gcd(a, b)

def list_lcm(start, length):
    if length == 0:
        return 1

    current_lcm = start
    for i in range(start + 1, start + length):
        current_lcm = lcm(current_lcm, i)
    return current_lcm

# Test n=1
n1_works = True
for k in range(1, 5):
    x_k = k
    x_k_plus_1 = k + 1
    if x_k_plus_1 <= x_k:
        n1_works = False
        break
print(f"n=1 works: {n1_works}")

# Test n=2
n2_works = True
for k in range(1, 5):
    x_k = list_lcm(k, 2)
    x_k_plus_1 = list_lcm(k+1, 2)
    if x_k_plus_1 <= x_k:
        n2_works = False
        break
print(f"n=2 works: {n2_works}")

import math
from functools import reduce

def lcm(a, b):
    return abs(a*b) // math.gcd(a, b)

def lcm_list(numbers):
    if not numbers:
        return 1
    return reduce(lcm, numbers)

n = 3
k_max = 100

# Calculate and store sequence values
x_values = {}
for k in range(1, k_max + 2):
    x_values[k] = lcm_list(range(k, k + n))

# Check for x_{k+1} <= x_k
fails = []
for k in range(1, k_max + 1):
    x_k = x_values[k]
    x_k_plus_1 = x_values[k+1]

    if x_k_plus_1 <= x_k:
        fails.append((k, x_k, x_k_plus_1))

print(f"Failures found for n=3 up to k={k_max}:")
if fails:
    for k, x_k, x_k_plus_1 in fails:
        print(f"k={k}: x_{k+1} ({x_k_plus_1}) <= x_k ({x_k})")
else:
    print("No failures found in the checked range.")
